using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
namespace Demo.Notes
{
    public static class Roles
    {
        public const string AllUsers = "AllUsers";
        public const string Editors = "Editors";
        // quien puede escribir notas
        public static readonly string[] Writers = { Editors, AllUsers };
    }

    public static class NotesEndpoints
    {
        public static void Map(WebApplication app)
        {
            app.MapGet("/notes", (NotesStore store) => store.List())
               .RequireAuthorization(p => p.RequireRole(Roles.Editors));
            app.MapPut("/notes/{id:int}", (int id, NoteDto dto, NotesStore store) => store.Save(id, dto))
               .RequireAuthorization(p => p.RequireRole(Roles.Writers));
        }
    }
}

