using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
namespace Demo.Drafts
{
    // la tabla: CREATE TABLE Drafts (Id INT IDENTITY, UserId INT, Body NVARCHAR(MAX), SavedAt DATETIME2)
    public static class DraftsEndpoints
    {
        public static void Map(WebApplication app)
        {
            app.MapPost("/drafts", async (HttpRequest request, DraftsStore store, CurrentUser user) =>
            {
                using var reader = new StreamReader(request.Body);
                var body = await reader.ReadToEndAsync();
                // una fila nueva por cada guardado
                await store.InsertAsync("INSERT INTO Drafts (UserId, Body, SavedAt) VALUES (@u, @b, SYSUTCDATETIME())", new { u = user.Id, b = body });
                return Results.NoContent();
            }).RequireAuthorization();
        }
    }
}

using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
namespace Demo.Drafts
{
    // la tabla: CREATE TABLE Drafts (UserId INT PRIMARY KEY, Body NVARCHAR(4000), SavedAt DATETIME2)
    public static class DraftsEndpoints
    {
        public const int MaxBytes = 8000;
        public static void Map(WebApplication app)
        {
            app.MapPost("/drafts", [RequestSizeLimit(MaxBytes)] async (HttpRequest request, DraftsStore store, CurrentUser user) =>
            {
                if (request.ContentLength is null or > MaxBytes) return Results.StatusCode(413);
                var dto = await request.ReadFromJsonAsync<DraftDto>();
                if (dto is null || dto.Body.Length > 4000) return Results.BadRequest();
                // un borrador por usuario: se actualiza, no se agrega
                await store.UpsertAsync("MERGE Drafts AS t USING (SELECT @u AS UserId) s ON t.UserId = s.UserId WHEN MATCHED THEN UPDATE SET Body = @b, SavedAt = SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT (UserId, Body, SavedAt) VALUES (@u, @b, SYSUTCDATETIME());", new { u = user.Id, b = dto.Body });
                return Results.NoContent();
            }).RequireAuthorization();
        }
    }
    public record DraftDto([property: System.ComponentModel.DataAnnotations.MaxLength(4000)] string Body);
}

