using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
namespace Demo.Integrations
{
    public record IntegrationDto(int Id, string Provider, string RawToken, System.DateTime ExpiresAt);

    public static class IntegrationsEndpoints
    {
        public static void Map(WebApplication app)
        {
            app.MapGet("/me/integration", (IntegrationsStore store, CurrentUser user) =>
            {
                var i = store.ForUser(user.Id);
                return Results.Ok(new IntegrationDto(i.Id, i.Provider, i.AccessToken, i.ExpiresAt));
            }).RequireAuthorization();
        }
    }
}

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
namespace Demo.Integrations
{
    public record IntegrationDto(int Id, string Provider, bool HasToken, string TokenLast4, System.DateTime ExpiresAt);

    public static class IntegrationsEndpoints
    {
        public static void Map(WebApplication app)
        {
            app.MapGet("/me/integration", (IntegrationsStore store, CurrentUser user) =>
            {
                var i = store.ForUser(user.Id);
                var last4 = string.IsNullOrEmpty(i.AccessToken) ? "" : i.AccessToken[^4..];
                return Results.Ok(new IntegrationDto(i.Id, i.Provider, !string.IsNullOrEmpty(i.AccessToken), last4, i.ExpiresAt));
            }).RequireAuthorization();
        }
    }
}
